<?php require_once __DIR__.'/config/db.php'; startAppSession(); if(isLoggedIn()){ header('Location: '.url(in_array($_SESSION['user_role'],['cashier','operator'])?'operator.php':'dashboard.php')); exit; } $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL); $password=$_POST['password']??''; if($email && $password){ $q=getDB()->prepare('SELECT u.*,c.name club_name FROM users u JOIN clubs c ON c.id=u.club_id WHERE u.email=? AND u.is_active=1 LIMIT 1'); $q->execute([$email]); $u=$q->fetch(); if($u && password_verify($password,$u['password'])){ session_regenerate_id(true); $_SESSION=['user_id'=>$u['id'],'user_name'=>$u['name'],'user_role'=>$u['role'],'club_id'=>$u['club_id'],'club_name'=>$u['club_name'],'csrf_token'=>bin2hex(random_bytes(32))]; $q=getDB()->prepare('UPDATE users SET last_login=NOW() WHERE id=?');$q->execute([$u['id']]); header('Location: '.url(in_array($u['role'],['cashier','operator'])?'operator.php':'dashboard.php'));exit;} audit('login_failed','user',null,null,['email'=>$email]); $error='Invalid email or password.'; } else $error='Enter a valid email and password.'; } ?>
